return [{
  json: {
    company: "Acme Analytics",
    website: "https://acme.example",
    employee_count: 85,
    engineering_team_size: 14,
    role: "Head of Growth",
    email: "maya@acme.example",
    existing_codebase: true,
    uses_ai_coding_tools: true,
    non_engineering_change_volume: "high",
    pain_point: "Marketing waits several days for engineering to make pricing and landing-page changes."
  }
}];

const src = $json.body ?? $json;
const asBool = (v) => v === true || String(v).toLowerCase() === 'true' || String(v).toLowerCase() === 'yes';
const num = (v) => Number(v || 0);
const role = String(src.role || '').toLowerCase();
const volume = String(src.non_engineering_change_volume || '').toLowerCase();
let score = 0;
const reasons = [];

if (asBool(src.existing_codebase)) { score += 25; reasons.push('existing production codebase'); }
if (num(src.engineering_team_size) >= 5) { score += 20; reasons.push('engineering team >= 5'); }
if (['high','medium'].includes(volume)) { score += volume === 'high' ? 15 : 10; reasons.push(`${volume} non-engineering change volume`); }
if (asBool(src.uses_ai_coding_tools)) { score += 15; reasons.push('already uses AI coding tools'); }
if (/(growth|marketing|operations|ops|product|sales|engineering|cto|founder)/.test(role)) { score += 15; reasons.push('relevant champion/validator role'); }
const employees = num(src.employee_count);
if (employees >= 20 && employees <= 500) { score += 10; reasons.push('20-500 employee test segment'); }

score = Math.min(score, 100);
const segment = score >= 70 ? 'A' : score >= 50 ? 'B' : 'C';
return [{ json: {
  ...src,
  icp_score: score,
  segment,
  score_reasons: reasons,
  scored_at: new Date().toISOString()
}}];

const x = $json;
const first = (x.role || 'there').split(' ')[0];
let route, cta, subject;
if (x.segment === 'A') {
  route = 'founder_outreach';
  cta = 'Would it be useful to test one real backlog item and see the PR Sparkles produces?';
  subject = `${x.company}: ship one backlog item without joining the engineering queue`;
} else if (x.segment === 'B') {
  route = 'nurture';
  cta = 'Worth a 10-minute look at how Sparkles keeps engineering review in the loop?';
  subject = `${x.company}: a safer way for non-engineers to ship small changes`;
} else {
  route = 'educate';
  cta = 'If this becomes a recurring bottleneck, I can send a 2-minute workflow example.';
  subject = `When ${x.company} starts feeling the engineering queue`;
}
const pain = x.pain_point || 'non-engineering teams depend on engineering for routine changes';
const message = `Hi ${first},\n\nI was looking at ${x.company} and your role in ${x.role || 'the team'}. The use case that stood out is: ${pain}\n\nSparkles lets non-engineering teammates request changes against an existing GitHub codebase while the work still comes back as a reviewable PR, so engineering keeps its normal controls.\n\n${cta}\n\n- Okechukwu`;
return [{ json: { ...x, route, subject, message } }];

const x = $json;
return [{json: {
  ...x,
  funnel_event: {
    event_name: 'gtm_lead_qualified',
    timestamp: new Date().toISOString(),
    distinct_id: x.email || `${x.company || 'unknown'}-${Date.now()}`,
    properties: {
      company: x.company,
      role: x.role,
      icp_score: x.icp_score,
      segment: x.segment,
      route: x.route,
      existing_codebase: x.existing_codebase,
      uses_ai_coding_tools: x.uses_ai_coding_tools,
      non_engineering_change_volume: x.non_engineering_change_volume
    }
  }
}}];
